package com.birdhouse.tracker;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Polygon;
import java.awt.Rectangle;
import net.runelite.client.ui.overlay.components.LayoutableRenderableEntity;

/** Compact inline amber warning triangle and label for the existing RuneLite overlay. */
final class BirdhouseDependencyWarningComponent implements LayoutableRenderableEntity
{
    static final String LABEL = "Time Tracking Disabled";
    static final Color ICON_COLOR = new Color(255, 190, 75);
    private static final Color ICON_MARK_COLOR = new Color(55, 43, 22);
    private static final Color TEXT_COLOR = Color.WHITE;
    private static final int ICON_SIZE = 11;
    private static final int GAP = 5;

    private final Rectangle bounds = new Rectangle();
    private Point preferredLocation = new Point();

    @Override
    public Dimension render(Graphics2D graphics)
    {
        FontMetrics metrics = graphics.getFontMetrics();
        int height = Math.max(metrics.getHeight(), ICON_SIZE);
        int iconX = preferredLocation.x;
        int iconY = preferredLocation.y + (height - ICON_SIZE) / 2;
        int centerX = iconX + ICON_SIZE / 2;

        Polygon triangle = new Polygon(
            new int[] {iconX, centerX, iconX + ICON_SIZE},
            new int[] {iconY + ICON_SIZE, iconY, iconY + ICON_SIZE}, 3);

        Color oldColor = graphics.getColor();
        graphics.setColor(ICON_COLOR);
        graphics.fillPolygon(triangle);
        graphics.setColor(ICON_MARK_COLOR);
        graphics.drawLine(centerX, iconY + 3, centerX, iconY + 7);
        graphics.fillOval(centerX - 1, iconY + 8, 2, 2);
        graphics.setColor(TEXT_COLOR);
        graphics.drawString(LABEL, iconX + ICON_SIZE + GAP,
            preferredLocation.y + metrics.getAscent());
        graphics.setColor(oldColor);

        int width = ICON_SIZE + GAP + metrics.stringWidth(LABEL);
        bounds.setBounds(preferredLocation.x, preferredLocation.y, width, height);
        return new Dimension(width, height);
    }

    @Override
    public Rectangle getBounds()
    {
        return bounds;
    }

    @Override
    public void setPreferredLocation(Point position)
    {
        preferredLocation = position == null ? new Point() : new Point(position);
    }

    @Override
    public void setPreferredSize(Dimension dimension)
    {
        // Width is determined by the RuneLite font metrics and compact icon.
    }
}

package com.birdhouse.tracker;

import java.awt.Color;
import java.awt.TrayIcon;
import javax.inject.Inject;
import net.runelite.api.ChatMessageType;
import net.runelite.client.Notifier;
import net.runelite.client.chat.ChatMessageBuilder;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.FlashNotification;
import net.runelite.client.config.Notification;
import net.runelite.client.config.NotificationSound;
import net.runelite.client.config.RequestFocusType;
import net.runelite.client.config.RuneLiteConfig;

/** READY delivery channels, shared by live events and founder-only smoke tests. */
final class BirdhouseNotificationDelivery
{
    static final Color CHAT_RED = new Color(255, 0, 0);
    static final String TIME_TRACKING_DISABLED_TEXT =
        "Birdhouse Timer: Time Tracking is disabled. Enable it in RuneLite Configuration > search \"Time Tracking\" > enable.";
    // Explicitly desktop-only to avoid the second, default-highlight chat message
    // that RuneLite's generic notifier can otherwise generate.
    private final ChatMessageManager chatMessageManager;
    private final Notifier notifier;
    private final RuneLiteConfig runeLiteConfig;

    @Inject
    BirdhouseNotificationDelivery(ChatMessageManager chatMessageManager, Notifier notifier,
        RuneLiteConfig runeLiteConfig)
    {
        this.chatMessageManager = chatMessageManager;
        this.notifier = notifier;
        this.runeLiteConfig = runeLiteConfig;
    }

    void sendReady(boolean redChatEnabled, boolean desktopEnabled)
    {
        dispatchReady(redChatEnabled, desktopEnabled, this::sendRedChat, this::sendDesktop);
    }

    /** Independent per-player READY choices; production and tests share this branch. */
    static void dispatchReady(boolean redChatEnabled, boolean desktopEnabled,
        Runnable redChat, Runnable desktop)
    {
        if (redChatEnabled)
        {
            try
            {
                redChat.run();
            }
            finally
            {
                // A chat failure must not prevent an enabled desktop attempt.
                if (desktopEnabled)
                {
                    desktop.run();
                }
            }
        }
        else if (desktopEnabled)
        {
            desktop.run();
        }
    }

    void sendRedChat()
    {
        String formatted = new ChatMessageBuilder()
            .append(CHAT_RED, BirdhouseWarningMessage.READY_TEXT)
            .build();
        chatMessageManager.queue(QueuedMessage.builder()
            .type(ChatMessageType.CONSOLE)
            .runeLiteFormattedMessage(formatted)
            .build());
    }

    void sendDesktop()
    {
        // Notifier only applies RuneLite's global focus rule when this per-notification
        // flag is false and the client is focused. Read the global preference at the
        // moment of delivery so user changes take effect without restarting the plugin.
        notifier.notify(desktopNotification(runeLiteConfig.sendNotificationsWhenFocused()),
            BirdhouseWarningMessage.READY_TEXT);
    }

    /** Desktop-only notification that follows RuneLite's global focus preference. */
    static Notification desktopNotification(boolean sendWhenFocused)
    {
        return new Notification(
            true, true, true, true, TrayIcon.MessageType.INFO,
            RequestFocusType.OFF, NotificationSound.OFF, null, 0, 0,
            false, FlashNotification.DISABLED, CHAT_RED, sendWhenFocused);
    }

    /** A dependency warning is not a READY alert and is independent of READY preferences. */
    void sendTimeTrackingDisabledWarning()
    {
        String formatted = new ChatMessageBuilder()
            .append(CHAT_RED, TIME_TRACKING_DISABLED_TEXT)
            .build();
        chatMessageManager.queue(QueuedMessage.builder()
            .type(ChatMessageType.CONSOLE)
            .runeLiteFormattedMessage(formatted)
            .build());
    }
}

package com.birdhouse.tracker;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.time.Instant;
import java.util.List;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

/** Movable game-screen overlay for active sites, with an explicit empty state. */
final class BirdhouseOverlay extends OverlayPanel
{
    static final int COMPACT_WIDTH_PX = 190;
    static final String EMPTY_STATE_MESSAGE = "No active birdhouses";
    static final String TITLE = "Birdhouse Timers";
    static final String DEMO_TITLE = TITLE + " [DM]";
    static final String TIME_TRACKING_INSTRUCTION_1 = "1. Open Configuration (wrench)";
    static final String TIME_TRACKING_INSTRUCTION_2 = "2. Search Time Tracking";
    static final String TIME_TRACKING_INSTRUCTION_3 = "3. Enable Time Tracking";
    static final Color READY_COLOR = new Color(0, 255, 0); // Bright green to match RuneLite Farming READY text.
    static final Color SOON_COLOR = new Color(255, 220, 50);
    static final Color GROWING_COLOR = new Color(255, 80, 80);
    static final Color DEPENDENCY_WARNING_COLOR = new Color(255, 190, 75);

    private final BirdhouseTrackerPlugin plugin;
    private final BirdhouseTrackerConfig config;

    @Inject
    BirdhouseOverlay(BirdhouseTrackerPlugin plugin, BirdhouseTrackerConfig config)
    {
        super(plugin);
        this.plugin = plugin;
        this.config = config;
        setPosition(OverlayPosition.TOP_LEFT);
        setPriority(PRIORITY_MED);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        List<BirdhouseTimer> timers = plugin.getTimers();
        panelComponent.setPreferredSize(new Dimension(COMPACT_WIDTH_PX, 0));
        panelComponent.getChildren().add(TitleComponent.builder()
            .text(config.demoMode() ? DEMO_TITLE : TITLE)
            .build());

        boolean dependencyWarning = TimeTrackingDependencyStatus.shouldShowOverlayWarning(
            config.demoMode(), plugin.isTimeTrackingStatusKnownForOverlay(),
            plugin.isTimeTrackingActiveForOverlay());
        if (dependencyWarning)
        {
            panelComponent.getChildren().add(new BirdhouseDependencyWarningComponent());
            panelComponent.getChildren().add(LineComponent.builder()
                .left("To enable:")
                .build());
            panelComponent.getChildren().add(LineComponent.builder()
                .left(TIME_TRACKING_INSTRUCTION_1)
                .build());
            panelComponent.getChildren().add(LineComponent.builder()
                .left(TIME_TRACKING_INSTRUCTION_2)
                .build());
            panelComponent.getChildren().add(LineComponent.builder()
                .left(TIME_TRACKING_INSTRUCTION_3)
                .build());
        }

        if (shouldShowEmptyState(timers.isEmpty(), dependencyWarning))
        {
            panelComponent.getChildren().add(LineComponent.builder()
                .left(EMPTY_STATE_MESSAGE)
                .build());
            return super.render(graphics);
        }
        if (timers.isEmpty())
        {
            // A dependency warning already explains why no current timers are shown.
            return super.render(graphics);
        }

        long now = Instant.now().getEpochSecond();
        for (BirdhouseTimer timer : timers)
        {
            long remaining = timer.secondsRemaining(now);
            Color statusColor = statusColor(remaining, config.warningLeadTime());
            String label = timer.site.displayLabel();
            panelComponent.getChildren().add(LineComponent.builder()
                .left(label)
                .leftColor(Color.WHITE)
                .right(timer.display(now))
                .rightColor(statusColor)
                .build());
        }
        return super.render(graphics);
    }

    static boolean shouldShowEmptyState(boolean timersEmpty, boolean dependencyWarning)
    {
        return timersEmpty && !dependencyWarning;
    }

    /** The existing advance-warning preference also controls the yellow visual cue. */
    static Color statusColor(long remainingSeconds, WarningLeadTime leadTime)
    {
        if (remainingSeconds <= 0)
        {
            // READY denotes the 50-minute estimate, not confirmed maturity.
            return READY_COLOR;
        }
        int warningMinutes = leadTime == null ? 0 : leadTime.minutes;
        return warningMinutes > 0 && remainingSeconds <= warningMinutes * 60L
            ? SOON_COLOR : GROWING_COLOR;
    }
}

package com.birdhouse.tracker;

/** Pure per-location cycle guard used before persisting and dispatching READY alerts. */
final class BirdhouseReadyCycleGate
{
    private BirdhouseReadyCycleGate()
    {
    }

    static boolean isNewCycle(String previouslyNotifiedCycle, String currentCycle)
    {
        return currentCycle != null && !currentCycle.equals(previouslyNotifiedCycle);
    }
}

package com.birdhouse.tracker;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/** Coalesces READY transitions first observed within a short fixed window. */
final class BirdhouseReadyNotificationBatcher
{
    static final long WINDOW_SECONDS = 10L;

    private final Map<String, BirdhouseTimer> pending = new LinkedHashMap<>();
    private long deadlineSeconds = Long.MIN_VALUE;

    void add(BirdhouseTimer timer, long observedAtSeconds)
    {
        if (timer == null)
        {
            return;
        }
        String key = timer.site.varp + ":" + timer.cycleKey;
        if (pending.isEmpty())
        {
            deadlineSeconds = observedAtSeconds + WINDOW_SECONDS;
        }
        pending.putIfAbsent(key, timer);
    }

    boolean isDue(long nowSeconds)
    {
        return !pending.isEmpty() && nowSeconds >= deadlineSeconds;
    }

    List<BirdhouseTimer> drain()
    {
        if (pending.isEmpty())
        {
            return java.util.Collections.emptyList();
        }
        List<BirdhouseTimer> result = new ArrayList<>(pending.values());
        pending.clear();
        deadlineSeconds = Long.MIN_VALUE;
        return result;
    }

    void clear()
    {
        pending.clear();
        deadlineSeconds = Long.MIN_VALUE;
    }

    int pendingCount()
    {
        return pending.size();
    }
}

package com.birdhouse.tracker;

import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import net.runelite.api.gameval.VarPlayerID;

/** The four Fossil Island birdhouse spaces as named by RuneLite Time Tracking. */
enum BirdhouseSite
{
    MEADOW_NORTH("Mushroom Meadow North", VarPlayerID.BIRDHOUSE_TRANSMIT_A),
    MEADOW_SOUTH("Mushroom Meadow South", VarPlayerID.BIRDHOUSE_TRANSMIT_B),
    VALLEY_NORTH("Verdant Valley NE", VarPlayerID.BIRDHOUSE_TRANSMIT_C),
    VALLEY_SOUTH("Verdant Valley SW", VarPlayerID.BIRDHOUSE_TRANSMIT_D);

    // Intentionally separate from enum declaration order so varp and persisted
    // notification identity remain stable. Never sort rows by maturity.
    private static final List<BirdhouseSite> DISPLAY_ORDER = Collections.unmodifiableList(
        Arrays.asList(MEADOW_SOUTH, MEADOW_NORTH, VALLEY_SOUTH, VALLEY_NORTH));

    final String label;
    final int varp;

    BirdhouseSite(String label, int varp)
    {
        this.label = label;
        this.varp = varp;
    }

    static List<BirdhouseSite> displayOrder()
    {
        return DISPLAY_ORDER;
    }

    /** Ceci's location label for the single compact overlay. */
    String displayLabel()
    {
        return label;
    }
}

package com.birdhouse.tracker;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/** A read-only interpretation of RuneLite's per-site Time Tracking record. */
final class BirdhouseTimer
{
    static final long MATURITY_SECONDS = 50 * 60L;
    private static final long EARLIEST_REASONABLE_TIMESTAMP = 1_500_000_000L;
    private static final long MAX_FUTURE_CLOCK_SKEW_SECONDS = 60 * 60L;

    final BirdhouseSite site;
    final int varpValue;
    final long plantedAt;
    final String cycleKey;

    private BirdhouseTimer(BirdhouseSite site, int varpValue, long plantedAt)
    {
        this.site = site;
        this.varpValue = varpValue;
        this.plantedAt = plantedAt;
        this.cycleKey = varpValue + ":" + plantedAt;
    }

    /** Return null for empty, built-but-unseeded, missing, or invalid states. */
    static BirdhouseTimer parse(BirdhouseSite site, String stored, long nowSeconds)
    {
        if (stored == null)
        {
            return null;
        }

        String[] parts = stored.split(":", -1);
        if (parts.length != 2)
        {
            return null;
        }

        try
        {
            int varp = Integer.parseInt(parts[0]);
            long timestamp = Long.parseLong(parts[1]);
            // RuneLite: positive, every third birdhouse value means it is seeded.
            // Nine birdhouse tiers, three states per tier.
            if (varp <= 0 || varp > 27 || varp % 3 != 0
                || timestamp < EARLIEST_REASONABLE_TIMESTAMP
                || timestamp > nowSeconds + MAX_FUTURE_CLOCK_SKEW_SECONDS)
            {
                return null;
            }
            return new BirdhouseTimer(site, varp, timestamp);
        }
        catch (NumberFormatException ex)
        {
            return null;
        }
    }

    /**
     * Purely illustrative countdowns. Demo values are never stored in RuneLite
     * configuration and never represent a player's actual birdhouses.
     */
    static List<BirdhouseTimer> demoTimers(long startedAt)
    {
        // READY, 4 minutes, 15 minutes and 42 minutes at demo start.
        int[] secondsAlreadyElapsed = {55 * 60, 46 * 60, 35 * 60, 8 * 60};
        List<BirdhouseSite> sites = BirdhouseSite.displayOrder();
        List<BirdhouseTimer> result = new ArrayList<>(sites.size());
        for (int i = 0; i < sites.size(); i++)
        {
            // "3" is a seeded tier in RuneLite's birdhouse varp encoding.
            BirdhouseTimer timer = parse(sites.get(i), "3:" + (startedAt - secondsAlreadyElapsed[i]), startedAt);
            if (timer != null)
            {
                result.add(timer);
            }
        }
        return Collections.unmodifiableList(result);
    }

    long secondsRemaining(long nowSeconds)
    {
        return plantedAt + MATURITY_SECONDS - nowSeconds;
    }

    String display(long nowSeconds)
    {
        long remaining = secondsRemaining(nowSeconds);
        if (remaining <= 0)
        {
            return "READY";
        }
        long minutes = remaining / 60;
        long seconds = remaining % 60;
        return String.format(java.util.Locale.ROOT, "%02d:%02d", minutes, seconds);
    }
}

package com.birdhouse.tracker;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("birdhousetracker")
public interface BirdhouseTrackerConfig extends Config
{
    @ConfigItem(
        keyName = "warningLeadTime",
        name = "Advance warning",
        description = "Notify once when any planted birdhouse is approaching readiness. "
            + "READY: The standard 50-minute birdhouse timer has elapsed. The birdhouse is estimated to be ready for harvesting, but completion is not guaranteed.",
        position = 0
    )
    default WarningLeadTime warningLeadTime()
    {
        return WarningLeadTime.TEN;
    }

    @ConfigItem(
        keyName = "demoMode",
        name = "Demo mode",
        description = "Preview four simulated birdhouse countdowns. This is a visual-only preview; it does not change real tracking data or send notifications.",
        position = 1
    )
    default boolean demoMode()
    {
        return false;
    }

    @ConfigItem(
        keyName = "readyRedChatEnabled",
        name = "READY: Red in-game chat",
        description = "Send the red in-game chat notification when a birdhouse reaches its estimated READY time.",
        position = 2
    )
    default boolean readyRedChatEnabled()
    {
        return true;
    }

    @ConfigItem(
        keyName = "readyDesktopEnabled",
        name = "READY: Windows desktop",
        description = "Send the Windows desktop notification when a birdhouse reaches its estimated READY time.",
        position = 3
    )
    default boolean readyDesktopEnabled()
    {
        return true;
    }

}

package com.birdhouse.tracker;

import com.google.inject.Provides;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.client.Notifier;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.PluginChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.PluginManager;
import net.runelite.client.plugins.timetracking.TimeTrackingPlugin;
import net.runelite.client.ui.overlay.OverlayManager;

/**
 * Read-only display of RuneLite's built-in Time Tracking birdhouse records.
 * The only saved records this plugin writes are its own notification markers.
 */
@PluginDescriptor(
    name = "Birdhouse Timer",
    description = "Visible planted birdhouse countdowns and advance warnings. "
        + "READY: The standard 50-minute birdhouse timer has elapsed. The birdhouse is estimated to be ready for harvesting, but completion is not guaranteed.",
    tags = {"birdhouse", "hunter", "fossilisland", "timer"}
)
public class BirdhouseTrackerPlugin extends Plugin
{
    private static final String SOURCE_GROUP = "timetracking";
    private static final String OWN_GROUP = "birdhousetracker";
    private static final String TIME_TRACKING_WARNING_SENT_KEY = "timeTrackingDisabledWarningSent";

    @Inject private Client client;
    @Inject private ConfigManager configManager;
    @Inject private PluginManager pluginManager;
    @Inject private BirdhouseTrackerConfig config;
    @Inject private OverlayManager overlayManager;
    @Inject private BirdhouseOverlay overlay;
    @Inject private Notifier notifier;
    @Inject private BirdhouseNotificationDelivery notificationDelivery;

    private final TimeTrackingDependencyStatus timeTrackingStatus = new TimeTrackingDependencyStatus();
    private final BirdhouseReadyNotificationBatcher readyBatcher = new BirdhouseReadyNotificationBatcher();
    private TimeTrackingPlugin timeTrackingPlugin;
    private volatile boolean loggedIn;
    private boolean deferDependencyWarningUntilFirstGameTick;

    private volatile List<BirdhouseTimer> timers = Collections.emptyList();
    private volatile List<BirdhouseTimer> demoTimers = Collections.emptyList();

    @Provides
    BirdhouseTrackerConfig provideConfig(ConfigManager manager)
    {
        return manager.getConfig(BirdhouseTrackerConfig.class);
    }

    @Override
    protected void startUp()
    {
        demoTimers = Collections.emptyList();
        timeTrackingPlugin = pluginManager.getPlugins().stream()
            .filter(TimeTrackingPlugin.class::isInstance)
            .map(TimeTrackingPlugin.class::cast)
            .findFirst()
            .orElse(null);
        loggedIn = client.getGameState() == GameState.LOGGED_IN;
        deferDependencyWarningUntilFirstGameTick = true;
        overlayManager.add(overlay);
        refresh();
    }

    @Override
    protected void shutDown()
    {
        overlayManager.remove(overlay);
        timers = Collections.emptyList();
        demoTimers = Collections.emptyList();
        readyBatcher.clear();
    }

    @Subscribe
    public void onGameTick(GameTick event)
    {
        updateTimeTrackingStatus(isTimeTrackingActive(), !deferDependencyWarningUntilFirstGameTick);
        deferDependencyWarningUntilFirstGameTick = false;
        refresh();
    }

    @Subscribe
    public void onPluginChanged(PluginChanged event)
    {
        if (event.getPlugin() == timeTrackingPlugin && !deferDependencyWarningUntilFirstGameTick)
        {
            updateTimeTrackingStatus(event.isLoaded(), true);
        }
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        loggedIn = event.getGameState() == GameState.LOGGED_IN;
        if (!loggedIn)
        {
            timers = Collections.emptyList();
        }
        else
        {
            if (!deferDependencyWarningUntilFirstGameTick)
            {
                updateTimeTrackingStatus(isTimeTrackingActive(), true);
            }
            refresh();
        }
    }

    private boolean isTimeTrackingActive()
    {
        return timeTrackingPlugin != null && pluginManager.isPluginActive(timeTrackingPlugin);
    }

    private void updateTimeTrackingStatus(boolean active, boolean allowInitialWarning)
    {
        boolean wasInitialized = timeTrackingStatus.isInitialized();
        boolean wasActive = timeTrackingStatus.isActive();
        if (active && (!wasInitialized || !wasActive))
        {
            // A transition into a new active episode resets only the dependency-warning latch.
            configManager.setConfiguration(OWN_GROUP, TIME_TRACKING_WARNING_SENT_KEY, false);
        }

        boolean mayWarn = allowInitialWarning && loggedIn && !config.demoMode();
        String warningSentValue = configManager.getConfiguration(OWN_GROUP, TIME_TRACKING_WARNING_SENT_KEY);
        boolean warningAlreadySent = Boolean.parseBoolean(warningSentValue);
        if (timeTrackingStatus.update(active, mayWarn, warningAlreadySent))
        {
            // Persist before delivery so ticks and client restarts cannot spam.
            configManager.setConfiguration(OWN_GROUP, TIME_TRACKING_WARNING_SENT_KEY, true);
            notificationDelivery.sendTimeTrackingDisabledWarning();
        }
    }

    boolean isTimeTrackingStatusKnownForOverlay()
    {
        return timeTrackingStatus.isInitialized();
    }

    boolean isTimeTrackingActiveForOverlay()
    {
        return timeTrackingStatus.isActive();
    }

    List<BirdhouseTimer> getTimers()
    {
        if (!config.demoMode())
        {
            // Clearing the preview makes a later re-enable start fresh.
            demoTimers = Collections.emptyList();
            return timers;
        }

        List<BirdhouseTimer> preview = demoTimers;
        if (preview.isEmpty())
        {
            preview = BirdhouseTimer.demoTimers(Instant.now().getEpochSecond());
            demoTimers = preview;
        }
        return preview;
    }

    private void refresh()
    {
        // Demo mode is strictly visual: do not read/write account timers or
        // issue real game notifications while the preview is enabled.
        if (config.demoMode())
        {
            timers = Collections.emptyList();
            return;
        }
        if (client.getGameState() != GameState.LOGGED_IN)
        {
            timers = Collections.emptyList();
            return;
        }

        long now = Instant.now().getEpochSecond();
        // Flush a short coalescing window before observing this tick's new events.
        // Pending cycle markers are written only when the combined alert is sent,
        // so a restart before dispatch lets the next refresh safely rediscover them.
        flushReadyBatch(now);

        List<BirdhouseTimer> active = new ArrayList<>(4);
        List<BirdhouseTimer> newlyWarned = new ArrayList<>(4);
        int lead = config.warningLeadTime().minutes;
        for (BirdhouseSite site : BirdhouseSite.displayOrder())
        {
            String saved = configManager.getRSProfileConfiguration(
                SOURCE_GROUP, "birdhouse." + site.varp);
            BirdhouseTimer timer = BirdhouseTimer.parse(site, saved, now);
            if (timer == null)
            {
                continue;
            }
            active.add(timer);
            long remaining = timer.secondsRemaining(now);
            // A separate per-site 50-minute READY marker ensures that READY and
            // advance-warning notifications never suppress one another.
            // The cycle key changes after replanting.
            if (remaining <= 0)
            {
                String readyKey = "ready." + site.varp;
                String lastReadyCycle = configManager.getRSProfileConfiguration(OWN_GROUP, readyKey);
                if (BirdhouseReadyCycleGate.isNewCycle(lastReadyCycle, timer.cycleKey))
                {
                    readyBatcher.add(timer, now);
                }
            }
            else if (lead > 0 && remaining <= lead * 60L)
            {
                String warningKey = "warned." + site.varp;
                String lastCycle = configManager.getRSProfileConfiguration(OWN_GROUP, warningKey);
                if (!timer.cycleKey.equals(lastCycle))
                {
                    // Persist before notifying to avoid spamming on relaunch.
                    configManager.setRSProfileConfiguration(OWN_GROUP, warningKey, timer.cycleKey);
                    newlyWarned.add(timer);
                }
            }
        }
        timers = Collections.unmodifiableList(active);
        if (!newlyWarned.isEmpty())
        {
            notifier.notify(BirdhouseWarningMessage.format(newlyWarned, lead));
        }
    }

    private void flushReadyBatch(long nowSeconds)
    {
        if (!readyBatcher.isDue(nowSeconds))
        {
            return;
        }

        List<BirdhouseTimer> batch = readyBatcher.drain();
        if (batch.isEmpty())
        {
            return;
        }

        // Persist every site's cycle marker before dispatch, retaining the existing
        // once-per-cycle guarantee for both red chat and desktop delivery.
        for (BirdhouseTimer timer : batch)
        {
            configManager.setRSProfileConfiguration(OWN_GROUP,
                "ready." + timer.site.varp, timer.cycleKey);
        }
        notificationDelivery.sendReady(config.readyRedChatEnabled(), config.readyDesktopEnabled());
    }

}

package com.birdhouse.tracker;

import java.util.List;
import java.util.stream.Collectors;

/** One readable notification for all locations entering a warning window together. */
final class BirdhouseWarningMessage
{
    static final String READY_TEXT =
        "Birdhouse Timer: Your birdhouse traps may now be ready to reset.";

    private BirdhouseWarningMessage()
    {
    }

    static String format(List<BirdhouseTimer> newlyWarned, int leadMinutes)
    {
        if (newlyWarned == null || newlyWarned.isEmpty())
        {
            throw new IllegalArgumentException("At least one birdhouse is required");
        }
        if (leadMinutes <= 0)
        {
            throw new IllegalArgumentException("Warning lead time must be positive");
        }
        String locations = newlyWarned.stream()
            .map(timer -> timer.site.displayLabel())
            .collect(Collectors.joining(", "));
        return (newlyWarned.size() == 1 ? "Birdhouse" : "Birdhouses")
            + " ready within " + leadMinutes + " minutes: " + locations + ".";
    }

    /** One approved estimated READY message for a single coalesced event batch. */
    static String formatReady(List<BirdhouseTimer> newlyReady)
    {
        if (newlyReady == null || newlyReady.isEmpty())
        {
            throw new IllegalArgumentException("At least one ready birdhouse is required");
        }
        // Approved single message for one or more newly READY sites.
        // Site grouping and per-cycle markers are handled by the plugin.
        return READY_TEXT;
    }
}

package com.birdhouse.tracker;

/** Tracks Time Tracking availability and computes one warning per inactive episode. */
final class TimeTrackingDependencyStatus
{
    private volatile boolean active;
    private volatile boolean initialized;

    /**
     * Updates dependency state and indicates whether a warning should be sent now.
     * The caller persists the warning marker so a client restart does not repeat it.
     */
    boolean update(boolean active, boolean maySendWarning, boolean warningAlreadySent)
    {
        this.active = active;
        this.initialized = true;
        return !active && maySendWarning && !warningAlreadySent;
    }

    boolean isInitialized()
    {
        return initialized;
    }

    boolean isActive()
    {
        return active;
    }

    static boolean shouldShowOverlayWarning(boolean demoMode, boolean initialized, boolean active)
    {
        return !demoMode && initialized && !active;
    }
}

