        String oldCycle = "9:1800000000";
        String newCycle = "9:1800003000";
        assertTrue(BirdhouseReadyCycleGate.isNewCycle(oldCycle, newCycle));
    }

    @Test
    public void nullCycleCannotTriggerNotification()
    {
        assertFalse(BirdhouseReadyCycleGate.isNewCycle(null, null));
    }
}

package com.birdhouse.tracker;

import java.util.List;
import org.junit.Test;
import static org.junit.Assert.*;

/** Fixed-window grouping tests; no RuneLite client is required. */
public class BirdhouseReadyNotificationBatcherTest
{
    private static final long NOW = 1_800_000_000L;

    private static BirdhouseTimer timer(BirdhouseSite site, long plantedAt)
    {
        return BirdhouseTimer.parse(site, "3:" + plantedAt, NOW);
    }

    @Test
    public void firstEventIsHeldForAtMostTenSeconds()
    {
        BirdhouseReadyNotificationBatcher batcher = new BirdhouseReadyNotificationBatcher();
        batcher.add(timer(BirdhouseSite.MEADOW_SOUTH, NOW - 3000), NOW);
        assertFalse(batcher.isDue(NOW + 9));
        assertTrue(batcher.isDue(NOW + 10));
    }

    @Test
    public void slightlyStaggeredSitesShareOneBatch()
    {
        BirdhouseReadyNotificationBatcher batcher = new BirdhouseReadyNotificationBatcher();
        batcher.add(timer(BirdhouseSite.MEADOW_SOUTH, NOW - 3000), NOW);
        batcher.add(timer(BirdhouseSite.MEADOW_NORTH, NOW - 3001), NOW + 8);
        assertFalse(batcher.isDue(NOW + 9));
        assertTrue(batcher.isDue(NOW + 10));
        List<BirdhouseTimer> batch = batcher.drain();
        assertEquals(2, batch.size());
        assertEquals(0, batcher.pendingCount());
    }

    @Test
    public void duplicateSameSiteSameCycleIsCoalesced()
    {
        BirdhouseReadyNotificationBatcher batcher = new BirdhouseReadyNotificationBatcher();
        BirdhouseTimer first = timer(BirdhouseSite.MEADOW_SOUTH, NOW - 3000);
        batcher.add(first, NOW);
        batcher.add(first, NOW + 1);
        assertEquals(1, batcher.pendingCount());
    }

    @Test
    public void eventsAfterWindowStartANewBatch()
    {
        BirdhouseReadyNotificationBatcher batcher = new BirdhouseReadyNotificationBatcher();
        batcher.add(timer(BirdhouseSite.MEADOW_SOUTH, NOW - 3000), NOW);
        assertEquals(1, batcher.drain().size());
        batcher.add(timer(BirdhouseSite.MEADOW_NORTH, NOW - 3001), NOW + 11);
        assertFalse(batcher.isDue(NOW + 20));
        assertTrue(batcher.isDue(NOW + 21));
    }

    @Test
    public void newBatcherHasNoPersistedPendingState()
    {
        BirdhouseReadyNotificationBatcher first = new BirdhouseReadyNotificationBatcher();
        first.add(timer(BirdhouseSite.MEADOW_SOUTH, NOW - 3000), NOW);
        BirdhouseReadyNotificationBatcher afterRestart = new BirdhouseReadyNotificationBatcher();
        assertEquals(0, afterRestart.pendingCount());
        // Production cycle markers are deliberately written only on dispatch,
        // allowing a restart during the pending window to rediscover the cycle.
        assertEquals(NOW + 10, NOW + BirdhouseReadyNotificationBatcher.WINDOW_SECONDS);
    }
}

package com.birdhouse.tracker;

import java.util.Arrays;
import java.util.Collections;
import org.junit.Test;
import static org.junit.Assert.*;

/** READY notification formatting and exact maturity boundaries. */
public class BirdhouseReadyNotificationTest
{
    private static final long NOW = 1_800_000_000L;

    private static BirdhouseTimer timer(BirdhouseSite site, long plantedAt)
    {
        return BirdhouseTimer.parse(site, "3:" + plantedAt, NOW);
    }

    @Test
    public void beforeMaturityIsNotReady()
    {
        assertEquals(1L, timer(BirdhouseSite.MEADOW_NORTH, NOW - 2999).secondsRemaining(NOW));
    }

    @Test
    public void exactlyMatureIsReady()
    {
        BirdhouseTimer t = timer(BirdhouseSite.MEADOW_NORTH, NOW - 3000);
        assertEquals(0L, t.secondsRemaining(NOW));
        assertEquals("READY", t.display(NOW));
    }

    @Test
    public void afterMaturityRemainsReady()
    {
        BirdhouseTimer t = timer(BirdhouseSite.MEADOW_NORTH, NOW - 3001);
        assertTrue(t.secondsRemaining(NOW) < 0);
        assertEquals("READY", t.display(NOW));
    }

    @Test
    public void singleReadyMessageNamesLocation()
    {
        assertEquals(BirdhouseWarningMessage.READY_TEXT,
            BirdhouseWarningMessage.formatReady(Collections.singletonList(
                timer(BirdhouseSite.MEADOW_SOUTH, NOW - 3000))));
    }

    @Test
    public void simultaneousReadyMessageGroupsLocations()
    {
        assertEquals(BirdhouseWarningMessage.READY_TEXT,
            BirdhouseWarningMessage.formatReady(Arrays.asList(
                timer(BirdhouseSite.MEADOW_NORTH, NOW - 3000),
                timer(BirdhouseSite.VALLEY_SOUTH, NOW - 3001))));
    }

    @Test
    public void readyWorksIndependentlyOfAdvanceWarningSetting()
    {
        BirdhouseTimer t = timer(BirdhouseSite.VALLEY_NORTH, NOW - 3000);
        assertEquals(BirdhouseWarningMessage.READY_TEXT,
            BirdhouseWarningMessage.formatReady(Collections.singletonList(t)));
    }

    @Test(expected = IllegalArgumentException.class)
    public void emptyReadyMessageIsInvalid()
    {
        BirdhouseWarningMessage.formatReady(Collections.emptyList());
    }

    @Test(expected = IllegalArgumentException.class)
    public void nullReadyMessageIsInvalid()
    {
        BirdhouseWarningMessage.formatReady(null);
    }
}

package com.birdhouse.tracker;

import org.junit.Test;
import static org.junit.Assert.*;

/** Dependency warning lifecycle tests; no RuneLite client or account data required. */
public class BirdhouseTimeTrackingDependencyStatusTest
{
    @Test
    public void inactiveDependencyWarnsOnceWhenLoggedIn()
    {
        TimeTrackingDependencyStatus status = new TimeTrackingDependencyStatus();
        assertFalse(status.isInitialized()); // unknown until first runtime sample
        assertFalse(status.update(false, false, false)); // defer while logged out
        assertTrue(status.update(false, true, false));
        assertFalse(status.update(false, true, true)); // persisted marker prevents repeated warnings
    }

    @Test
    public void reactivationResetsWarningForNextInactiveEpisode()
    {
        TimeTrackingDependencyStatus status = new TimeTrackingDependencyStatus();
        assertTrue(status.update(false, true, false));
        assertFalse(status.update(false, true, true));
        assertFalse(status.update(true, true, true));
        assertTrue(status.isActive());
        assertTrue(status.update(false, true, false));
        assertFalse(status.update(false, true, true));
    }

    @Test
    public void demoModeSuppressesDependencyWarningAndOverlayIndicator()
    {
        TimeTrackingDependencyStatus status = new TimeTrackingDependencyStatus();
        assertFalse(status.update(false, false, false)); // caller suppresses chat while in Demo Mode
        assertTrue(TimeTrackingDependencyStatus.shouldShowOverlayWarning(false, true, false));
        assertFalse(TimeTrackingDependencyStatus.shouldShowOverlayWarning(true, true, false));
        assertFalse(TimeTrackingDependencyStatus.shouldShowOverlayWarning(false, true, true));
        assertFalse(TimeTrackingDependencyStatus.shouldShowOverlayWarning(false, false, false));
    }

    @Test
    public void dependencyWarningRemainsPendingUntilLoggedIn()
    {
        TimeTrackingDependencyStatus status = new TimeTrackingDependencyStatus();
        assertFalse(status.update(false, false, false));
        assertFalse(status.update(false, false, false));
        assertTrue(status.update(false, true, false));
    }

    @Test
    public void firstObservationDoesNotPretendTheDependencyIsInactive()
    {
        TimeTrackingDependencyStatus status = new TimeTrackingDependencyStatus();
        assertFalse(status.isInitialized()); // unknown until first runtime sample
        assertFalse(status.update(false, false, false));
        assertTrue(status.isInitialized());
        assertFalse(status.isActive());
    }

    @Test
    public void persistedWarningMarkerSurvivesAStatusObjectRestart()
    {
        TimeTrackingDependencyStatus firstRun = new TimeTrackingDependencyStatus();
        assertTrue(firstRun.update(false, true, false));

        TimeTrackingDependencyStatus afterRestart = new TimeTrackingDependencyStatus();
        assertFalse(afterRestart.update(false, true, true));
    }
}

